#!/usr/bin/env node
// Bundles the canonical readiness model into the backend functions that need it.
//
// Same problem, same solution as the routing engine: the Base44 bundler rejects
// relative imports that cross a function folder boundary, so each function gets
// its own copy. A hand-written mirror would drift, so the copy is GENERATED from
// src/lib/progress/readiness.js and guarded by a parity check.
//
// There is exactly one source of truth for how readiness is calculated. If the
// frontend and the backend ever disagree about whether the platform is ready,
// that is a defect, not a difference of opinion.
//
// Run:  node scripts/generate-progress-bundle.mjs
//       node scripts/generate-progress-bundle.mjs --check   (exit 1 if drifted)

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = join(ROOT, 'src/lib/progress/readiness.js');
const TARGETS = [
  'base44/functions/progressReadiness/readiness.js',
  'base44/functions/progressPrompt/readiness.js',
];

const CHECK_ONLY = process.argv.includes('--check');

const HEADER = [
  '// GENERATED by scripts/generate-progress-bundle.mjs. Do not edit by hand.',
  '// Canonical source: src/lib/progress/readiness.js',
  '// Edit the source, then re-run the generator. The parity check gates on this.',
  '',
].join('\n');

if (!existsSync(SOURCE)) {
  console.error(`canonical readiness model missing at ${SOURCE}`);
  process.exit(1);
}

const source = readFileSync(SOURCE, 'utf8');
const bundled = `${HEADER}${source}`;

let drifted = [];
for (const rel of TARGETS) {
  const target = join(ROOT, rel);
  const current = existsSync(target) ? readFileSync(target, 'utf8') : null;
  if (current !== bundled) drifted.push(rel);
}

if (CHECK_ONLY) {
  if (drifted.length > 0) {
    console.error('progress bundle DRIFTED from the canonical model:');
    drifted.forEach((d) => console.error(`  ${d}`));
    console.error('Run: node scripts/generate-progress-bundle.mjs');
    process.exit(1);
  }
  console.log(`progress bundle OK: ${TARGETS.length} backend copies match src/lib/progress/readiness.js`);
  process.exit(0);
}

for (const rel of TARGETS) {
  const target = join(ROOT, rel);
  const dir = dirname(target);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  writeFileSync(target, bundled);
}

console.log(`progress bundle written: ${TARGETS.length} copies`);
TARGETS.forEach((t) => console.log(`  ${t}`));
if (drifted.length === 0) console.log('  (no change)');
